import React, { useEffect, useMemo, useState } from 'react';
import { Menu, Spin, message } from 'antd';
import { useNavigate, useLocation } from 'react-router-dom';
import {
  MessageOutlined,
  SettingOutlined,
  BulbOutlined,
  TagsOutlined,
  CalendarOutlined,
  ToolOutlined,
  CreditCardOutlined,
  HomeOutlined,
  QuestionCircleOutlined,
  SafetyOutlined,
} from '@ant-design/icons';
import { usePermissions, usePlatform } from '../hooks/usePermissions';
import { buildAuthHeaders } from '../api';
import type { UIConfig as UIConfigUnified, UIMenuItem, UIMenuGroup } from '../types/ui';
import { inferGroupByPath } from '../types/ui';

// Маппинг иконок
const iconMap = {
  MessageOutlined,
  SettingOutlined,
  BulbOutlined,
  TagsOutlined,
  CalendarOutlined,
  ToolOutlined,
  CreditCardOutlined,
  HomeOutlined,
  QuestionCircleOutlined,
  SafetyOutlined,
};

// Локальные интерфейсы заменены унифицированными типами из ../types/ui

interface PermissionBasedMenuProps {
  inlineCollapsed?: boolean;
}

const PermissionBasedMenu: React.FC<PermissionBasedMenuProps> = ({ inlineCollapsed = false }) => {
  const navigate = useNavigate();
  const location = useLocation();
  const { state: permissionsState } = usePermissions();
  const { platform, isMiniApp } = usePlatform();
  
  const [uiConfig, setUiConfig] = useState<UIConfigUnified | null>(null);
  const [loading, setLoading] = useState(true);

  // Загрузка конфигурации UI
  useEffect(() => {
    const fetchUIConfig = async () => {
      try {
        setLoading(true);

        // P23/P22: предпочитаем новый фасад /api/ui/config с фолбеком на /api/user/ui-config
        let response = await fetch('/api/ui/config', { headers: buildAuthHeaders() });
        if (!response.ok) {
          response = await fetch('/api/user/ui-config', { headers: buildAuthHeaders() });
        }

        if (!response.ok) {
          throw new Error(`HTTP ${response.status}`);
        }

        const config: UIConfigUnified = await response.json();
        // Фолбек: гарантируем пункты для Архитектора, даже если сервер отдал урезанный меню‑набор
        try {
          const roles: string[] = Array.isArray(config.roles) ? config.roles : [];
          const isArchitect = roles.includes('architect') || String(config.user_id || '') === '468326902';
          const items: UIMenuItem[] = Array.isArray(config.menu_items) ? [...config.menu_items] : [];
          const ensureItem = (key: string, label: string, icon: string, path: string) => {
            if (!items.some(i => i.key === key)) {
              items.push({ key, label, icon, path, group: inferGroupByPath(path) });
            }
          };
          if (isArchitect) {
            // Главный пункт: открывает хаб Архитектора
            ensureItem('architect', 'Панель Архитектора', 'ToolOutlined', '/architect');
            ensureItem('soul-dashboard', 'Soul Dashboard', 'ToolOutlined', '/soul/dashboard');
            ensureItem('soul-goals', 'Цели Soul', 'ToolOutlined', '/soul/goals');
            ensureItem('soul-logs', 'Логи', 'ToolOutlined', '/soul/logs');
          }
          setUiConfig({ ...config, menu_items: items });
        } catch {
          setUiConfig(config);
        }
      } catch (error) {
        console.error('Ошибка загрузки конфигурации UI:', error);
        message.error('Не удалось загрузить конфигурацию меню');
        
        // Fallback конфигурация
        // Если мы в Телеграм мини‑апп и это Архитектор (tg_id=468326902), показываем панели управления Soul даже при сбое API
        try {
          const tgId = (typeof window !== 'undefined' && (window as any).Telegram?.WebApp?.initDataUnsafe?.user?.id?.toString())
            || (typeof window !== 'undefined' && window.sessionStorage?.getItem('tg_id'))
            || '';
          const isArchitectRoman = tgId === '468326902';

          const baseItems: UIMenuItem[] = [
            { key: 'chat', label: 'Чат', icon: 'MessageOutlined', path: '/chat', group: 'chat' },
            { key: 'dates-reminders', label: 'Даты и напоминания', icon: 'CalendarOutlined', path: '/dates-reminders', group: 'core' },
            { key: 'settings', label: 'Настройки', icon: 'SettingOutlined', path: '/settings', group: 'settings' },
          ];
          const archItems: UIMenuItem[] = isArchitectRoman ? [
            { key: 'architect', label: 'Панель Архитектора', icon: 'ToolOutlined', path: '/architect', group: 'admin' },
            { key: 'rbac-admin', label: 'RBAC Управление', icon: 'SafetyOutlined', path: '/rbac-admin', group: 'admin' },
            { key: 'soul-dashboard', label: 'Soul Dashboard', icon: 'ToolOutlined', path: '/soul/dashboard', group: 'soul' },
            { key: 'soul-goals', label: 'Цели Soul', icon: 'ToolOutlined', path: '/soul/goals', group: 'soul' },
            { key: 'soul-logs', label: 'Логи', icon: 'ToolOutlined', path: '/soul/logs', group: 'soul' },
          ] : [];

          setUiConfig({
            user_id: isArchitectRoman ? Number(tgId) : 0,
            roles: isArchitectRoman ? ['architect'] : ['basic'],
            menu_items: [...baseItems, ...archItems, { key: 'payments', label: 'Подписки', icon: 'CreditCardOutlined', path: '/payments' }],
            features: { chat: true, admin_panel: isArchitectRoman, llm_advanced: isArchitectRoman },
            ui_theme: 'default',
          });
        } catch {
          setUiConfig({
            user_id: 0,
            roles: ['basic'],
            menu_items: [
              { key: 'chat', label: 'Чат', icon: 'MessageOutlined', path: '/chat' },
              { key: 'settings', label: 'Настройки', icon: 'SettingOutlined', path: '/settings' },
            ],
            features: { chat: true },
            ui_theme: 'default',
          });
        }
      } finally {
        setLoading(false);
      }
    };

    // Загружаем конфигурацию только после загрузки полномочий
    if (!permissionsState.loading) {
      fetchUIConfig();
    }
  }, [permissionsState.loading]);

  // Обработка клика по пункту меню
  const handleMenuClick = (item: { key: string }) => {
    const menuItem = uiConfig?.menu_items.find(mi => mi.key === item.key);
    if (menuItem) {
      navigate(menuItem.path);
    }
  };

  // Мемо: активный ключ и сгруппированные пункты
  const selectedKeys = useMemo(() => {
    if (!uiConfig) return [] as string[];
    const currentPath = location.pathname;
    const activeItem = uiConfig.menu_items.find(item => item.path === currentPath);
    return activeItem ? [activeItem.key] : [];
  }, [uiConfig, location.pathname]);

  const groupedItems = useMemo(() => {
    const groups: Record<UIMenuGroup, UIMenuItem[]> = { core: [], chat: [], soul: [], admin: [], settings: [] } as any;
    (uiConfig?.menu_items || []).forEach(mi => {
      const g = (mi.group || inferGroupByPath(mi.path)) as UIMenuGroup;
      groups[g] = groups[g] || [];
      groups[g].push(mi);
    });
    return groups;
  }, [uiConfig]);

  // Рендеринг иконки
  const renderIcon = (iconName: string) => {
    const IconComponent = iconMap[iconName as keyof typeof iconMap];
    return IconComponent ? <IconComponent /> : <QuestionCircleOutlined />;
  };

  // Адаптация меню для мини-апп
  const getMenuMode = () => {
    return isMiniApp ? 'horizontal' : 'inline';
  };

  if (loading || permissionsState.loading) {
    return (
      <div style={{ padding: '20px', textAlign: 'center' }}>
        <Spin size="large" />
      </div>
    );
  }

  if (!uiConfig) {
    return (
      <div style={{ padding: '20px', textAlign: 'center' }}>
        <p>Не удалось загрузить меню</p>
      </div>
    );
  }

  // Специальная обработка для мини-апп
  if (isMiniApp) {
    return (
      <Menu
        mode="horizontal"
        selectedKeys={selectedKeys}
        onClick={handleMenuClick}
        style={{
          borderBottom: 'none',
          backgroundColor: 'transparent',
          justifyContent: 'center',
        }}
        items={(uiConfig.menu_items).map(item => ({
          key: item.key,
          icon: renderIcon(item.icon),
          label: item.label,
        }))}
      />
    );
  }

  // Обычное меню для веб-версии
  return (
    <Menu
      mode="inline"
      selectedKeys={selectedKeys}
      onClick={handleMenuClick}
      style={{ height: '100%', borderRight: 0 }}
      inlineCollapsed={inlineCollapsed}
      items={(uiConfig.menu_items).map(item => ({
        key: item.key,
        icon: renderIcon(item.icon),
        label: item.label,
      }))}
    />
  );
};

export default PermissionBasedMenu;
