import React from 'react';
import { useNavigate } from 'react-router-dom';
import { usePermissions } from '../hooks/usePermissions';

const TelegramHome: React.FC = () => {
  const navigate = useNavigate();

  const { state } = usePermissions();
  const isArchitect = state.roles.some(r => r.name === 'architect');
  const isAdmin = state.roles.some(r => r.name === 'admin');

  const features = [
    {
      id: 'mini-chat',
      icon: '💬',
      title: 'Чат в приложении',
      description: 'Полноценный чат с удалением сообщений',
      color: 'var(--sp-color-primary)',
      route: '/chat'
    },
    {
      id: 'telegram-chat',
      icon: '✉️',
      title: 'Телеграм-чат',
      description: 'Альтернативный интерфейс чата',
      color: 'var(--sp-color-secondary)',
      route: '/telegram-chat'
    },
    {
      id: 'chat-management',
      icon: '🗂️', 
      title: 'Управление чатом',
      description: 'Массовое удаление, статистика, синхронизация',
      color: 'var(--sp-color-secondary)',
      route: '/chat-management'
    },
    {
      id: 'prompts',
      icon: '/android-chrome-192x192.png',
      title: 'Личности',
      description: 'Выбор AI личности для общения', // updated
      color: 'var(--sp-color-accent)',
      route: '/prompts'
    },
    {
      id: 'permission-demo',
      icon: '🔐',
      title: 'Демо доступа',
      description: 'Проверка ролей и прав (RBAC)',
      color: 'var(--sp-color-accent)',
      route: '/permission-demo'
    },
    {
      id: 'settings',
      icon: '⚙️',
      title: 'Настройки',
      description: 'Конфигурация приложения',
      color: 'var(--sp-color-success)',
      route: '/settings'
    },
    {
      id: 'llm-settings',
      icon: '🧠',
      title: 'LLM настройки',
      description: 'Провайдеры и параметры моделей',
      color: 'var(--sp-color-primary)',
      route: '/llm-settings'
    },
    {
      id: 'keywords',
      icon: '🏷️',
      title: 'Ключевые слова',
      description: 'Управление ключевыми словами',
      color: 'var(--sp-color-accent)',
      route: '/keywords'
    },
    {
      id: 'dates-reminders',
      icon: '📅',
      title: 'Даты и напоминания',
      description: 'Календарь событий и напоминаний',
      color: 'var(--sp-color-success)',
      route: '/dates-reminders'
    },
    {
      id: 'payments',
      icon: '💳',
      title: 'Платежи',
      description: 'Оплата и подписки',
      color: 'var(--sp-color-secondary)',
      route: '/payments'
    },
    {
      id: 'help',
      icon: '❓',
      title: 'Помощь',
      description: 'Справка и поддержка',
      color: 'var(--sp-color-secondary)',
      route: '/help'
    }
  ];

  if (isAdmin || isArchitect) {
    features.push({
      id: 'admin',
      icon: '🛡️',
      title: 'Администрирование',
      description: 'Промокоды и заявки',
      color: 'var(--sp-color-accent)',
      route: '/admin'
    });
  }

  if (isArchitect) {
    features.push({
      id: 'architect',
      icon: '🧩',
      title: 'Панель Архитектора',
      description: 'Модели, лимиты, настройки',
      color: 'var(--sp-color-secondary)',
      route: '/architect'
    });
    features.push({
      id: 'trace',
      icon: '🧭',
      title: 'Trace',
      description: 'Цепочка от webhook до ответа',
      color: 'var(--sp-color-primary)',
      route: '/trace'
    });
    features.push({
      id: 'rbac-admin',
      icon: '🧷',
      title: 'RBAC Admin',
      description: 'Роли и права системы',
      color: 'var(--sp-color-secondary)',
      route: '/rbac-admin'
    });
    
    // Soul страницы для Архитектора
    features.push({
      id: 'soul-dashboard',
      icon: '🧠',
      title: 'Soul Dashboard',
      description: 'Мониторинг системы Soul',
      color: 'var(--sp-color-primary)',
      route: '/soul/dashboard'
    });
    
    features.push({
      id: 'soul-optimization',
      icon: '⚡',
      title: 'Soul Оптимизация',
      description: 'Управление оптимизацией Soul',
      color: 'var(--sp-color-accent)',
      route: '/soul/optimization'
    });
    
    features.push({
      id: 'soul-visualization',
      icon: '🌐',
      title: 'Soul Визуализация',
      description: 'Граф квантов сознания',
      color: 'var(--sp-color-success)',
      route: '/soul/visualization'
    });
    features.push({
      id: 'soul-logs',
      icon: '📜',
      title: 'Soul Логи',
      description: 'Потоки логов, фильтр и скачивание',
      color: 'var(--sp-color-primary)',
      route: '/soul/logs'
    });
  }

  if (isAdmin && !features.some(f => f.id === 'soul-logs')) {
    features.push({
      id: 'soul-logs',
      icon: '📜',
      title: 'Soul Логи',
      description: 'Потоки логов, фильтр и скачивание',
      color: 'var(--sp-color-primary)',
      route: '/soul/logs'
    });
  }

  const requestWebAccess = async () => {
    try {
      const telegramUser = (window as any).Telegram?.WebApp?.initDataUnsafe?.user;
      const tgId = telegramUser?.id;
      
      if (!telegramUser || !tgId) {
        alert('❌ Не удается получить данные пользователя Telegram');
        return;
      }

      console.log('[WEB_ACCESS] 🚀 Создаем веб доступ для пользователя:', telegramUser);
      
      const headers: Record<string, string> = {};
      if (tgId) headers['X-Telegram-User-ID'] = String(tgId);
      
      const resp = await fetch('/api/web-auth/issue-one-time-token', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', ...headers },
      });
      
      if (!resp.ok) {
        const t = await resp.text();
        alert(`Ошибка выдачи web-доступа: ${t}`);
        return;
      }
      
      const data = await resp.json();
      const otp = data.otp;
      const issuedTgId = data.tg_id || tgId;
      
      // Готовим данные пользователя для передачи в URL
      const userDataForUrl = {
        id: telegramUser.id,
        first_name: telegramUser.first_name,
        last_name: telegramUser.last_name,
        username: telegramUser.username,
        language_code: telegramUser.language_code,
        photo_url: telegramUser.photo_url
      };
      
      const origin = (window.location && window.location.origin) || 'https://test.soulpulse.art';
      
      // Создаем URL с данными пользователя И OTP токеном (двойная защита)
      const userDataEncoded = encodeURIComponent(JSON.stringify(userDataForUrl));
      const url = `${origin}/webauth?tg_id=${encodeURIComponent(issuedTgId)}&otp=${encodeURIComponent(otp)}&user_data=${userDataEncoded}`;

      console.log('[WEB_ACCESS] 🔗 Создана ссылка:', url);

      // Показать код и ссылку
      const container = document.createElement('div');
      container.style.lineHeight = '1.6';
      container.style.fontSize = '14px';
      
      const title = document.createElement('div');
      title.innerHTML = '✅ Веб-доступ выдан на 5 минут';
      title.style.fontSize = '16px';
      title.style.fontWeight = 'bold';
      title.style.marginBottom = '16px';
      title.style.color = 'var(--sp-color-success)';
      
      const info = document.createElement('div');
      info.style.marginBottom = '16px';
      info.innerHTML = `
        <div style="margin-bottom: 8px;"><strong>OTP:</strong> <code style="background: #f1f5f9; padding: 2px 6px; border-radius: 4px; font-family: monospace;">${otp}</code></div>
        <div style="margin-bottom: 8px;"><strong>Telegram ID:</strong> ${issuedTgId}</div>
        <div><strong>Пользователь:</strong> ${telegramUser.first_name} ${telegramUser.last_name || ''}</div>
      `;
      
      const linkSection = document.createElement('div');
      linkSection.innerHTML = `
        <div style="margin-bottom: 8px; font-weight: bold;">Ссылка для браузера:</div>
        <a href="${url}" target="_blank" rel="noopener" style="
          display: inline-block;
          background: #3B82F6;
          color: white;
          text-decoration: none;
          padding: 8px 16px;
          border-radius: 6px;
          font-size: 13px;
          margin-bottom: 8px;
        ">🔗 Открыть веб-версию</a>
        <div style="font-size: 12px; color: var(--sp-text-secondary); word-break: break-all;">${url}</div>
      `;
      
      container.appendChild(title);
      container.appendChild(info);
      container.appendChild(linkSection);
      const wrap = document.createElement('div');
      wrap.style.position = 'fixed';
      wrap.style.inset = '0';
      wrap.style.background = 'rgba(0,0,0,0.5)';
      wrap.style.display = 'flex';
      wrap.style.alignItems = 'center';
      wrap.style.justifyContent = 'center';
      const modal = document.createElement('div');
      modal.style.background = '#fff';
      modal.style.padding = '16px';
      modal.style.borderRadius = '8px';
      modal.style.maxWidth = '480px';
      modal.style.fontSize = '14px';
      modal.appendChild(container);
      const ok = document.createElement('button');
      ok.textContent = 'OK';
      ok.style.marginTop = '12px';
      ok.onclick = () => document.body.removeChild(wrap);
      modal.appendChild(ok);
      wrap.appendChild(modal);
      document.body.appendChild(wrap);

      // Не открываем автоматически — пользователь должен успеть записать код
    } catch (e) {
      console.error(e);
      alert('Ошибка выдачи веб-доступа');
    }
  };

  return (
    <div className="telegram-home sp-edge-highlight" style={{
      background: 'var(--sp-gradient-background)',
      minHeight: '100vh',
      color: 'var(--sp-text-primary)',
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif'
    }}>
      {/* Компактный заголовок только с описанием */}
      <div style={{
        backgroundColor: 'var(--sp-bg-secondary)',
        padding: 'var(--sp-spacing-xs) var(--sp-spacing-md)',
        borderBottom: '1px solid var(--sp-border-primary)',
        position: 'sticky',
        top: 0,
        zIndex: 100,
        textAlign: 'center'
      }}>
        <p style={{
          margin: 0,
          fontSize: 'var(--sp-font-size-sm)',
          color: 'var(--sp-text-secondary)',
          fontWeight: '400'
        }}>
          Интеллектуальный чат-бот
        </p>
      </div>

      {/* Main Content */}
      <div className="sp-card-elevated sp-edge-highlight" style={{ padding: '20px', margin: '16px' }}>
        {/* Quick Actions */}
        <div style={{ marginBottom: '24px' }}>
          <h2 style={{
            fontSize: '16px',
            fontWeight: '500',
            color: 'var(--sp-text-primary)',
            margin: '0 0 16px 0'
          }}>
            Быстрые действия
          </h2>
          
          <div style={{
            display: 'grid',
            gap: '12px'
          }}>
            {features.map((feature) => (
              <div
                key={feature.id}
                onClick={() => navigate(feature.route)}
                role="button"
                tabIndex={0}
                onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') navigate(feature.route); }}
                className="telegram-home-feature-card sp-edge-highlight"
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: '12px'
                }}
              >
                <div style={{
                  fontSize: '24px',
                  minWidth: '32px',
                  textAlign: 'center'
                }}>
                  {feature.icon.startsWith('/') ? (
                    <img 
                      src={feature.icon} 
                      alt={feature.title}
                      style={{ 
                        width: '24px', 
                        height: '24px',
                        objectFit: 'contain'
                      }} 
                    />
                  ) : (
                    feature.icon
                  )}
                </div>
                <div style={{ flex: 1 }}>
                  <h3 style={{
                    margin: 0,
                    fontSize: '16px',
                    fontWeight: '500',
                    color: 'var(--sp-text-primary)',
                    marginBottom: '2px'
                  }}>
                    {feature.title}
                  </h3>
                  <p style={{
                    margin: 0,
                    fontSize: '14px',
                    color: 'var(--sp-text-secondary)',
                    lineHeight: '1.3'
                  }}>
                    {feature.description}
                  </p>
                </div>
                <div style={{
                  fontSize: '18px',
                  color: 'var(--sp-text-secondary)'
                }}>
                  →
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Info Section */}
        <div className="telegram-home-info-card sp-card-elevated sp-edge-highlight" style={{
          marginBottom: '20px'
        }}>
          <h3 style={{
            margin: '0 0 8px 0',
            fontSize: '16px',
            fontWeight: '500',
            color: 'var(--sp-text-primary)'
          }}>
            ℹ️ О приложении
          </h3>
          <p style={{
            margin: 0,
            fontSize: '14px',
            color: 'var(--sp-text-secondary)',
            lineHeight: '1.4'
          }}>
            SoulPulse v2.22 - новый чат в мини-приложении с полным управлением сообщениями. 
            Обходит все ограничения Telegram Bot API.
          </p>
        </div>

        {/* Recommendations */}
        <div className="telegram-home-recommendation-card">
          <h3 style={{
            margin: '0 0 8px 0',
            fontSize: '16px',
            fontWeight: '500',
            color: 'var(--sp-text-primary)',
            display: 'flex',
            alignItems: 'center',
            gap: '8px'
          }}>
            🌟 Рекомендуется
          </h3>
          <p style={{
            margin: '0 0 12px 0',
            fontSize: '14px',
            color: 'var(--sp-text-secondary)',
            lineHeight: '1.4'
          }}>
            Для лучшего опыта используйте <strong style={{ color: 'var(--sp-text-primary)' }}>Чат в приложении</strong> - 
            полный контроль над сообщениями без ограничений Telegram.
          </p>
          <button
            onClick={() => navigate('/chat')}
            className="telegram-home-button"
          >
            💬 Открыть чат в приложении
          </button>
          <div style={{ height: 12 }} />
          <button
            onClick={requestWebAccess}
            className="telegram-home-button success"
          >
            🔓 Открыть web‑доступ (5 мин)
          </button>
        </div>
      </div>
    </div>
  );
};

export default TelegramHome;
