import { theme } from 'antd';
import { colors, typography, spacing, borderRadius, shadows, platform } from './design-tokens';

// ===== БАЗОВАЯ ТЕМА =====

interface Theme {
  name: string;
  colors: {
    // Основные цвета
    primary: string;
    primaryHover: string;
    secondary: string;
    accent: string;
    
    // Фоны
    background: {
      primary: string;
      secondary: string;
      tertiary: string;
      card: string;
      hover: string;
      overlay: string;
    };
    
    // Тексты
    text: {
      primary: string;
      secondary: string;
      tertiary: string;
      inverse: string;
      disabled: string;
    };
    
    // Границы
    border: {
      primary: string;
      secondary: string;
      focus: string;
    };
    
    // Семантические цвета
    success: string;
    warning: string;
    danger: string;
    info: string;
    
    // Градиенты
    gradients: {
      primary: string;
      background: string;
      card: string;
    };
  };
  
  // Тени
  shadows: {
    sm: string;
    md: string;
    lg: string;
    glow: string;
  };
  
  // Специфичные для платформы настройки
  platform: {
    telegram: {
      background: string;
      header: string;
      bottomMenu: string;
    };
    web: {
      background: string;
      header: string;
      sidebar: string;
    };
  };
}

