// ===== АВТОМАТИЧЕСКАЯ ТЕМА =====

export const autoTheme: Theme = {
  name: 'auto',
  // Автоматическая тема наследует от темной по умолчанию
  // В runtime будет переключаться на основе системных настроек
  ...darkTheme,
};

// ===== КОЛЛЕКЦИЯ ТЕМ =====

export const themes = {
  dark: darkTheme,
  light: lightTheme,
  auto: autoTheme,
} as const;

export type ThemeName = keyof typeof themes;

// ===== ГЕНЕРАЦИЯ CSS ПЕРЕМЕННЫХ =====

export const generateCSSVariables = (theme: Theme): Record<string, string> => {
  return {
    // Основные цвета
    '--sp-color-primary': theme.colors.primary,
    '--sp-color-primary-hover': theme.colors.primaryHover,
    '--sp-color-secondary': theme.colors.secondary,
    '--sp-color-accent': theme.colors.accent,
    
    // Фоны
    '--sp-bg-primary': theme.colors.background.primary,
    '--sp-bg-secondary': theme.colors.background.secondary,
    '--sp-bg-tertiary': theme.colors.background.tertiary,
    '--sp-bg-card': theme.colors.background.card,
    '--sp-bg-hover': theme.colors.background.hover,
    '--sp-bg-overlay': theme.colors.background.overlay,
    
    // Тексты
    '--sp-text-primary': theme.colors.text.primary,
    '--sp-text-secondary': theme.colors.text.secondary,
    '--sp-text-tertiary': theme.colors.text.tertiary,
    '--sp-text-inverse': theme.colors.text.inverse,
    '--sp-text-disabled': theme.colors.text.disabled,
    
    // Границы
    '--sp-border-primary': theme.colors.border.primary,
    '--sp-border-secondary': theme.colors.border.secondary,
    '--sp-border-focus': theme.colors.border.focus,
    
    // Семантические цвета
    '--sp-color-success': theme.colors.success,
    '--sp-color-warning': theme.colors.warning,
    '--sp-color-danger': theme.colors.danger,
    '--sp-color-info': theme.colors.info,
    
    // Градиенты
    '--sp-gradient-primary': theme.colors.gradients.primary,
    '--sp-gradient-background': theme.colors.gradients.background,
    '--sp-gradient-card': theme.colors.gradients.card,
    
    // Тени
    '--sp-shadow-sm': theme.shadows.sm,
    '--sp-shadow-md': theme.shadows.md,
    '--sp-shadow-lg': theme.shadows.lg,
    '--sp-shadow-glow': theme.shadows.glow,
    
    // Размеры и отступы
    '--sp-spacing-xs': spacing[1],
    '--sp-spacing-sm': spacing[2],
    '--sp-spacing-md': spacing[4],
    '--sp-spacing-lg': spacing[6],
    '--sp-spacing-xl': spacing[8],
    
    // Радиусы
    '--sp-radius-sm': borderRadius.sm,
    '--sp-radius-md': borderRadius.md,
    '--sp-radius-lg': borderRadius.lg,
    '--sp-radius-xl': borderRadius.xl,
    
    // Типография
    '--sp-font-family': typography.fontFamily.sans,
    '--sp-font-mono': typography.fontFamily.mono,
    
    // Платформенные настройки
    '--sp-platform-header-height': platform.web.headerHeight,
    '--sp-platform-sidebar-width': platform.web.sidebarWidth,
  };
};

// ===== УТИЛИТЫ ДЛЯ РАБОТЫ С ТЕМАМИ =====

export const applyTheme = (themeName: ThemeName, element: HTMLElement = document.documentElement) => {
  const theme = themes[themeName];
  const cssVariables = generateCSSVariables(theme);
  
  // Применяем CSS переменные
  Object.entries(cssVariables).forEach(([property, value]) => {
    element.style.setProperty(property, value);
  });
  
  // Добавляем класс темы
  element.classList.remove('sp-theme-dark', 'sp-theme-light', 'sp-theme-auto');
  element.classList.add(`sp-theme-${themeName}`);
  
  // Сохраняем в localStorage
  localStorage.setItem('sp_theme', themeName);
};

export const getCurrentTheme = (): ThemeName => {
  const saved = localStorage.getItem('sp_theme') as ThemeName;
  if (saved && themes[saved]) {
    return saved;
  }
  
  // Определяем по системным настройкам
  if (window.matchMedia && window.matchMedia('(prefers-color-scheme: light)').matches) {
    return 'light';
  }
  
  return 'dark'; // По умолчанию темная
};

export const getSystemTheme = (): 'light' | 'dark' => {
  if (window.matchMedia && window.matchMedia('(prefers-color-scheme: light)').matches) {
    return 'light';
  }
  return 'dark';
};

export const resolveAutoTheme = (): 'light' | 'dark' => {
  return getSystemTheme();
};

// ===== ANT DESIGN ИНТЕГРАЦИЯ =====

export const getAntdThemeConfig = (themeName: ThemeName, isMiniApp: boolean = false) => {
  const themeObj = themes[themeName];
  const actualTheme = themeName === 'auto' ? themes[resolveAutoTheme()] : themeObj;
  
  return {
    algorithm: actualTheme.name === 'dark' ? theme.darkAlgorithm : theme.defaultAlgorithm,
    token: {
      colorPrimary: actualTheme.colors.primary,
      colorSuccess: actualTheme.colors.success,
      colorWarning: actualTheme.colors.warning,
      colorError: actualTheme.colors.danger,
      colorInfo: actualTheme.colors.info,
      
      colorBgContainer: actualTheme.colors.background.card,
      colorBgElevated: actualTheme.colors.background.secondary,
      colorBgLayout: actualTheme.colors.background.primary,
      
      colorText: actualTheme.colors.text.primary,
      colorTextSecondary: actualTheme.colors.text.secondary,
      colorTextTertiary: actualTheme.colors.text.tertiary,
      colorTextDisabled: actualTheme.colors.text.disabled,
      
      colorBorder: actualTheme.colors.border.primary,
      colorBorderSecondary: actualTheme.colors.border.secondary,
      
      borderRadius: isMiniApp ? 8 : 12,
      wireframe: false,
      
      fontFamily: typography.fontFamily.sans,
      fontSize: 14,
      
      boxShadow: actualTheme.shadows.md,
      boxShadowSecondary: actualTheme.shadows.sm,
    },
    components: {
      Card: {
        colorBgContainer: actualTheme.colors.background.card,
        colorBorderSecondary: actualTheme.colors.border.secondary,
      },
      Button: {
        colorPrimary: actualTheme.colors.primary,
        colorPrimaryHover: actualTheme.colors.primaryHover,
        borderRadius: isMiniApp ? 8 : 12,
      },
      Input: {
        colorBgContainer: actualTheme.colors.background.secondary,
        colorBorder: actualTheme.colors.border.primary,
        borderRadius: isMiniApp ? 6 : 8,
      },
      Menu: {
        colorBgContainer: 'transparent',
        itemBg: 'transparent',
        itemHoverBg: actualTheme.colors.background.hover,
        itemSelectedBg: actualTheme.colors.primary + '20', // 20% opacity
        itemActiveBg: actualTheme.colors.background.hover,
        itemSelectedColor: actualTheme.colors.text.primary,
        itemHoverColor: actualTheme.colors.text.primary,
        itemColor: actualTheme.colors.text.secondary,
      },
    },
  };
};

export default themes;
