// Типы данных
type User = {
  id: number;
  username: string;
  first_name: string;
  last_name: string;
  language_code: string;
  is_premium: boolean;
  allows_write_to_pm: boolean;
  photo_url?: string;
  auth_date: number;
  hash: string;
  subscription_status: string;
};

type Prompt = {
  id: number;
  name: string;
  description: string;
  category: string;
  is_active: boolean;
  is_base: boolean;
  can_work_alone?: boolean;
  icon_color?: string;
  icon_emoji?: string;
  locale?: string;
  key?: string;
  features?: string;
  target_audience?: string;
  activation_triggers?: string;
  kind?: string;
  sort_order?: number;
  usage_count?: number;
  rating?: number;
  created_at?: string;
  updated_at?: string;
  // Глобальная настройка, прокидываемая API для активного промпта
  disable_base_personality?: boolean;
  deep_memory_only?: boolean;
};

export default function App() {
  const SAFE_BOOT = (() => {
    try { return (window as any).__SP_FLAGS__?.SAFE_BOOT === true; } catch { return false; }
  })();
  const [user, setUser] = useState<User | null>(null);
  const [authError, setAuthError] = useState<string | null>(null);
  const [prompts, setPrompts] = useState<Prompt[]>([]);
  const [selectedPrompt, setSelectedPrompt] = useState<Prompt | null>(null);
  const [activePersonality, setActivePersonality] = useState<string>("SoulPulse");
  const [disableBasePersonality, setDisableBasePersonality] = useState(false);
  const [loading, setLoading] = useState(true);
  const [mounted, setMounted] = useState(false);
  
  // Детект Telegram WebApp один раз на старте, чтобы не менять тип роутера во время жизни приложения
  const initialIsTelegramRef = React.useRef<boolean>(false);
  if (initialIsTelegramRef.current === false) {
    try {
      const hasSdk = typeof window !== 'undefined' && !!(window as any).Telegram?.WebApp;
      const ua = (typeof navigator !== 'undefined' && navigator.userAgent) || '';
      const fromTg = /Telegram/i.test(ua) || (typeof document !== 'undefined' && /t\.me|telegram\.org/i.test(document.referrer || ''));
      initialIsTelegramRef.current = hasSdk || fromTg;
    } catch {
      initialIsTelegramRef.current = false;
    }
  }
  // Определяем факт запуска внутри Telegram WebView устойчиво (без ожидания tg_id)
  const isTelegramWebApp = (() => {
    try {
      if (initialIsTelegramRef.current) return true;
      const hasSdk = typeof window !== 'undefined' && !!(window as any).Telegram?.WebApp;
      const ua = (typeof navigator !== 'undefined' && navigator.userAgent) || '';
      const fromTg = /Telegram/i.test(ua) || (typeof document !== 'undefined' && /t\.me|telegram\.org/i.test(document.referrer || ''));
      return hasSdk || fromTg;
    } catch {
      return false;
    }
  })();

  // Используем новую систему тем
  const { getAntdConfig, resolvedTheme } = useTheme();

  // Применение платформенных классов
  const applyPlatformClasses = useCallback(() => {
    try {
      const bodyEl = document.body as HTMLElement;
      if (!bodyEl) return;
      
      console.log('🎨 Применяем платформенные классы, isTelegramWebApp:', isTelegramWebApp);
      
      // Очищаем старые классы
      bodyEl.classList.remove('theme-dark-indigo','theme-dark-slate','theme-light-indigo', 'telegram-mini-app');
      
      // Добавляем класс Mini App если нужно
      if (isTelegramWebApp) {
        bodyEl.classList.add('telegram-mini-app', 'sp-platform-telegram');
      } else {
        bodyEl.classList.add('sp-platform-web');
      }
      
      console.log('✅ Платформенные классы применены');
    } catch (e) {
      console.warn('Platform classes apply error:', e);
    }
  }, [isTelegramWebApp]);

  // Гейт на монтирование, чтобы исключить гонки инициализации WebView/SDK
  useEffect(() => {
    const t = setTimeout(() => setMounted(true), 0);
    return () => clearTimeout(t);
  }, []);


  // moved isTelegramWebApp above

  // Отладочная информация
  useEffect(() => {
    console.log('🔍 Debug Telegram WebApp detection:');
    console.log('- window.Telegram exists:', !!(window as any).Telegram);
    console.log('- WebApp exists:', !!(window as any).Telegram?.WebApp);
    console.log('- initDataUnsafe.user exists:', !!(window as any).Telegram?.WebApp?.initDataUnsafe?.user);
    console.log('- isTelegramWebApp:', isTelegramWebApp);
    console.log('- Resolved theme:', resolvedTheme);
    
    // Применяем платформенные классы
    applyPlatformClasses();
    console.log('- CSS class will be applied:', isTelegramWebApp ? 'telegram-mini-app' : 'none');
  }, [isTelegramWebApp, resolvedTheme, applyPlatformClasses]);

  // Утилиты работы с цветом
  const normalizeHex = (hex?: string): string | null => {
    if (!hex) return null;
    const v = hex.trim();
    if (/^#([0-9a-fA-F]{3}){1,2}$/.test(v)) return v;
    if (/^([0-9a-fA-F]{3}){1,2}$/.test(v)) return `#${v}`;
    return null;
  };

  const adjustLightness = (hex: string, percent: number): string => {
    const n = normalizeHex(hex) || '#6b46c1';
    const h = n.replace('#', '');
    const hh = h.length === 3 ? h.split('').map(c => c + c).join('') : h;
    const r = parseInt(hh.substring(0,2), 16);
    const g = parseInt(hh.substring(2,4), 16);
    const b = parseInt(hh.substring(4,6), 16);
    const p = Math.max(-100, Math.min(100, percent)) / 100;
    const t = p < 0 ? 0 : 255;
    const calc = (c: number) => Math.round(Math.sqrt((1 - Math.abs(p)))*c + Math.abs(p)*t);
    const rr = Math.max(0, Math.min(255, calc(r)));
    const gg = Math.max(0, Math.min(255, calc(g)));
    const bb = Math.max(0, Math.min(255, calc(b)));
    const toHex = (c: number) => c.toString(16).padStart(2, '0');
    return `#${toHex(rr)}${toHex(gg)}${toHex(bb)}`;
  };

  // Применение динамического градиента на уровне CSS переменных
  const applyGradient = (start: string, end: string) => {
    const root = document.documentElement;
    root.style.setProperty('--grad-start', start);
    root.style.setProperty('--grad-end', end);
  };

  // Загружаем промпты
  const loadPrompts = useCallback(async () => {
    try {
      console.log('🔄 Загружаем промпты из БД...');
      // Гарантируем авторизацию Telegram и получение tg_id
      const tgUser = getTelegramUser();
      const tgId = (tgUser && (tgUser as any).id) || sessionStorage.getItem('tg_id');
      if (!tgId) {
        throw new Error('401 Unauthorized: Telegram user id not found');
      }
      const response = await apiRequest(
        "/miniapp/prompts",
        "GET",
        null,
        { "X-Telegram-User-ID": String(tgId) }
      );
      const items = response.items;
      console.log('✅ Личности загружены из БД:', items);
      // Мягкая дедупликация по key+locale (или по id, если key отсутствует)
      const uniqueItems = Array.from(
        new Map(
          items.map((p) => [
            `${p.key || `id:${p.id}`}|${p.locale || 'ru'}`,
            p
          ])
        ).values()
      );
      setPrompts(uniqueItems);
      
      // Находим активный промпт
      const activePrompt = items.find(p => p.is_active);
      if (activePrompt) {
        console.log('🎯 Найден активный промпт:', activePrompt.name);
        setActivePersonality(activePrompt.name);
        setSelectedPrompt(activePrompt);
        
        // Устанавливаем состояние disable_base_personality из данных API (глобальная настройка)
        const disableBase = activePrompt.disable_base_personality || false;
        setDisableBasePersonality(disableBase);
        console.log(`🔧 Установлено disable_base_personality = ${disableBase} для ${activePrompt.name} (глобальная настройка)`);
        
        // Больше не загружаем пользовательские настройки - используем только глобальные
      } else {
        console.log('⚠️ Активный промпт не найден, используем базовый');
        // Если активный промпт не найден, ищем базовый "SoulPulse" (key = prompt-4)
        const basePrompt = items.find(p => p.key === 'prompt-4');
        if (basePrompt) {
          setActivePersonality(basePrompt.name);
          setSelectedPrompt(basePrompt);
          // Устанавливаем глобальную настройку для базового промпта
          const disableBase = basePrompt.disable_base_personality || false;
          setDisableBasePersonality(disableBase);
          console.log(`🔧 Установлено disable_base_personality = ${disableBase} для базового промпта ${basePrompt.name}`);
        }
      }
    } catch (error) {
      console.error('❌ Ошибка загрузки промптов:', error);
    } finally {
      setLoading(false); // Всегда сбрасываем загрузку
    }
  }, []); // Пустой массив зависимостей - функция стабильна

  // Загружаем настройки пользователя
  const loadUserSettings = async (promptKey: string) => {
    try {
      console.log(`🔄 Загружаем настройки пользователя для промпта: ${promptKey}`);
      
      // Проверяем, не загружаем ли мы уже настройки для этого промпта
      if (!promptKey) {
        console.log('⚠️ Нет ключа промпта для загрузки настроек');
        return;
      }
      
      const response = await api<{ disable_base_personality: boolean }>("/miniapp/prompts/dev/settings");
      console.log('✅ Настройки пользователя загружены:', response);

      // Обновляем состояние только если значение изменилось
      const newValue = response.disable_base_personality || false;
      if (newValue !== disableBasePersonality) {
        setDisableBasePersonality(newValue);
        console.log(`✅ Состояние disableBasePersonality обновлено: ${newValue}`);
      } else {
        console.log(`ℹ️ Состояние disableBasePersonality не изменилось: ${newValue}`);
      }
    } catch (error) {
      console.error('❌ Ошибка загрузки настроек пользователя:', error);
      // В случае ошибки используем значение по умолчанию
      setDisableBasePersonality(false);
    }
  };

  // Устанавливаем активную личность
  const handleSetActivePersonality = async (promptKey: string) => {
    try {
      console.log(`🔄 Устанавливаем активную личность: ${promptKey}`);
      
      const tgUser = getTelegramUser();
      const tgId = (tgUser && (tgUser as any).id) || sessionStorage.getItem('tg_id');
      if (!tgId) throw new Error('401 Unauthorized: Telegram user id not found');

      const formData = new FormData();
      formData.append("prompt_key", promptKey);
      // Не передаем disable_base - пусть бэкенд сам определит по can_work_alone
      
      const response = await fetch('/api/miniapp/prompts/dev/set-active', {
        method: 'POST',
        body: formData,
        headers: { 'X-Telegram-User-ID': String(tgId) }
      });
      
      if (response.ok) {
        const data = await response.json();
        // Устанавливаем настройку из ответа API (дефолтное значение на основе can_work_alone)
        const disableBase = data.disable_base_personality || false;
        setDisableBasePersonality(disableBase);
        setActivePersonality(data.active_prompt.name);
        // Мгновенно отражаем переключение в списке промптов
        setPrompts((prev) =>
          prev.map((p) => ({
            ...p,
            is_active: p.key === promptKey,
            disable_base_personality: p.key === promptKey ? disableBase : p.disable_base_personality,
          }))
        );
        
        // Обновляем список из БД для гарантированной синхронизации состояния
        await loadPrompts();
        
        console.log(`✅ Активная личность установлена: ${data.active_prompt.name}`);
        console.log(`✅ Глобальная настройка применена: disable_base_personality = ${disableBase}`);
      }
    } catch (error) {
      console.error('❌ Ошибка установки активной личности:', error);
    }
  };

  // Обновляем настройку без смены промпта
  const handleUpdateSettings = async (disableBase: boolean) => {
    try {
      console.log(`🔄 Обновляем настройку: disable_base_personality = ${disableBase}`);
      
      const tgUser = getTelegramUser();
      const tgId = (tgUser && (tgUser as any).id) || sessionStorage.getItem('tg_id');
      if (!tgId) throw new Error('401 Unauthorized: Telegram user id not found');

      const formData = new FormData();
      formData.append("disable_base", disableBase.toString());
      
      const response = await fetch('/api/miniapp/prompts/update-settings', {
        method: 'POST',
        body: formData,
        headers: { 'X-Telegram-User-ID': String(tgId) }
      });
      
      if (response.ok) {
        const data = await response.json();
        setDisableBasePersonality(disableBase);
        console.log(`✅ Настройка обновлена: disable_base_personality = ${disableBase}`);
      }
    } catch (error) {
      console.error('❌ Ошибка обновления настроек:', error);
      // Откатываем состояние при ошибке
      setDisableBasePersonality(!disableBase);
    }
  };

  // Обработчик изменения статуса промпта
  const handlePromptStatusChange = async (promptId: number, newStatus: boolean) => {
    try {
      const prompt = prompts.find(p => p.id === promptId);
      if (prompt && prompt.key) {
        if (newStatus) {
          await handleSetActivePersonality(prompt.key);
        } else {
          await handleSetActivePersonality('tikhiy_chekhov');
        }
      }
    } catch (error) {
      console.error('Ошибка изменения статуса промпта:', error);
    }
  };

  // Обработчик выбора промпта
  const handlePromptSelect = (prompt: Prompt) => {
    setSelectedPrompt(prompt);
  };

  // Инициализация приложения
  useEffect(() => {
    const initializeApp = async () => {
      try {
        console.log('🚀 Инициализация приложения...');
        
        if (isTelegramWebApp) {
          console.log('✅ Приложение запущено из Telegram WebApp');

          // Применяем CSS класс для Telegram стилей
          document.body.classList.add('telegram-mini-app');

          // Сообщаем Telegram, что приложение готово
          try {
            (window as any).Telegram?.WebApp?.ready?.();
          } catch {}

          // Сообщаем Telegram о готовности и расширяем
          try { (window as any).Telegram?.WebApp?.ready?.(); (window as any).Telegram?.WebApp?.expand?.(); } catch {}

          // Получаем данные пользователя из Telegram
          const telegramUser = (window as any).Telegram?.WebApp?.initDataUnsafe?.user;
          if (telegramUser && telegramUser.id) {
            console.log('👤 Пользователь Telegram найден:', telegramUser);
            setUser({
              id: telegramUser.id,
              username: telegramUser.username || '',
              first_name: telegramUser.first_name || '',
              last_name: telegramUser.last_name || '',
              language_code: telegramUser.language_code || 'ru',
              is_premium: telegramUser.is_premium || false,
              allows_write_to_pm: telegramUser.allows_write_to_pm || false,
              photo_url: telegramUser.photo_url || '',
              auth_date: Math.floor(Date.now() / 1000),
              hash: '',
              subscription_status: 'free'
            });
          } else {
            console.warn('⚠️ Telegram user не определён немедленно. Продолжаем без блокировки.');
            // Не блокируем Mini‑App: пробуем взять tg_id из sessionStorage (если ранее был) и продолжаем
            const tgId = sessionStorage.getItem('tg_id');
            if (tgId) {
              try {
                setUser({
                  id: parseInt(tgId, 10),
                  username: '',
                  first_name: '',
                  last_name: '',
                  language_code: 'ru',
                  is_premium: false,
                  allows_write_to_pm: false,
                  photo_url: '',
                  auth_date: Math.floor(Date.now() / 1000),
                  hash: '',
                  subscription_status: 'free'
                });
              } catch {}
            }
          }
        } else {
          console.warn('🌐 Приложение запущено НЕ из Telegram WebApp');

          // Проверяем, есть ли сохраненные данные пользователя из предыдущей сессии
          const savedUser = sessionStorage.getItem('telegram_user');
          const savedTgId = sessionStorage.getItem('tg_id');

          if (savedUser && savedTgId) {
            try {
              const telegramUser = JSON.parse(savedUser);
              console.log('✅ Найдены сохраненные данные пользователя:', telegramUser.id);
              setUser({
                id: telegramUser.id,
                username: telegramUser.username || '',
                first_name: telegramUser.first_name || '',
                last_name: telegramUser.last_name || '',
                language_code: telegramUser.language_code || 'ru',
                is_premium: telegramUser.is_premium || false,
                allows_write_to_pm: telegramUser.allows_write_to_pm || false,
                photo_url: telegramUser.photo_url || '',
                auth_date: Math.floor(Date.now() / 1000),
                hash: '',
                subscription_status: 'free'
              });
            } catch (e) {
              console.warn('❌ Ошибка парсинга сохраненных данных пользователя');
              setAuthError('Ошибка авторизации. Пожалуйста, войдите заново.');
              setLoading(false);
              return;
            }
          } else {
            console.warn('❌ Авторизация отсутствует. Показываем страницу входа.');
            setAuthError('Требуется авторизация через Telegram мини-приложение');
            setLoading(false);
            return;
          }
        }
        
        // Загружаем промпты и настройки
        await loadPrompts();
        
        console.log('✅ Приложение инициализировано');
      } catch (error) {
        console.error('❌ Ошибка инициализации приложения:', error);
        setLoading(false); // Сбрасываем загрузку при ошибке
      }
    };

    initializeApp();
    // Применяем платформенные классы при инициализации
    applyPlatformClasses();
    
    // Слушаем изменения localStorage (включая из других вкладок)
    const onStorage = (e: StorageEvent) => {
      if (e.key === 'sp_theme') {
        console.log('📱 localStorage изменился:', e.newValue);
        setTimeout(applyPlatformClasses, 10);
      }
    };
    
    // Слушаем кастомные события внутри страницы
    const onThemeChange = () => {
      console.log('🔄 Кастомное событие смены темы');
      setTimeout(applyPlatformClasses, 10);
    };
    
    window.addEventListener('storage', onStorage);
    window.addEventListener('themeChange', onThemeChange);
    
    return () => {
      window.removeEventListener('storage', onStorage);
      window.removeEventListener('themeChange', onThemeChange);
    };
  }, [isTelegramWebApp, applyPlatformClasses]);

  // Обновляем фон при изменении выбранного или активных промптов
  useEffect(() => {
    const source = selectedPrompt || prompts.find(p => p.is_active) || null;
    const base = normalizeHex(source?.icon_color) || '#1a1a3a';
    const start = adjustLightness(base, 10);
    const end = adjustLightness(base, -35);
    applyGradient(start, end);
  }, [selectedPrompt, prompts]);

  // Получаем имя активной личности для отображения
  const getActivePersonalityName = () => {
    return activePersonality || "SoulPulse";
  };

  // Тема Ant Design управляется через useTheme.getAntdConfig

  if (loading) {
    return (
      <div className="screen loading">
        <div className="loading-spinner">
          <div className="spinner"></div>
          <h2>Загрузка SoulPulse...</h2>
        </div>
      </div>
    );
  }

  const pathname = typeof window !== 'undefined' ? window.location.pathname : '';
  // Временная мера: не показывать WebAuth автоматически, чтобы не провоцировать цикл
  if (false && authError && !isTelegramWebApp) {
    return <WebAuth />;
  }

  // Если в Telegram нет tg_id, показываем мягкий экран авторизации вместо падения
  const isTg = isTelegramWebApp;
  const hasTgId = !!(typeof window !== 'undefined' && (sessionStorage.getItem('tg_id')));
  if (isTg && !hasTgId) {
    return (
      <div className="screen" style={{display:'flex',alignItems:'center',justifyContent:'center',minHeight:'100vh',color:'#fff',background:'#0f172a'}}>
        <div style={{maxWidth:560,padding:16,fontFamily:'ui-sans-serif, system-ui'}}>
          <h2 style={{marginTop:0}}>Требуется разрешение Telegram</h2>
          <p>Пожалуйста, перезапустите Mini‑App из кнопки бота, чтобы передать данные пользователя (initData).</p>
          <p>Если проблема остаётся — отправьте скрин, включу альтернативный путь входа.</p>
        </div>
      </div>
    );
  }

  // В веб-режиме без tg_id показываем WebAuth (без смены URL), чтобы избежать React #300/роутинг-гонок
  if (!isTg && !hasTgId) {
    return <WebAuth />;
  }

  // Безопасный запуск: минимальный рендер без AntD Layout/сложных компонентов
  if (SAFE_BOOT && isTelegramWebApp) {
    const SafeMiniAppScreen: React.FC = () => {
      let waAvailable = false;
      let uid: string | null = null;
      try {
        const wa = (window as any).Telegram?.WebApp;
        waAvailable = !!wa;
        uid = wa?.initDataUnsafe?.user?.id ? String(wa.initDataUnsafe.user.id) : null;
      } catch {}
      const stored = (() => { try { return sessionStorage.getItem('tg_id'); } catch { return null; } })();
      if (!stored && uid) {
        try { sessionStorage.setItem('tg_id', uid); } catch {}
      }
      return (
        <div style={{padding:16, fontFamily:'ui-monospace, monospace', background:'#0f172a', color:'#e5e7eb', minHeight:'100vh'}}>
          <div style={{fontWeight:700, marginBottom:8}}>MiniApp safe React screen</div>
          <div style={{fontSize:12, lineHeight:1.6}}>
            <div>wa: {String(waAvailable)}</div>
            <div>uid: {uid || 'null'}</div>
            <div>sessionStorage.tg_id: {stored || uid || 'null'}</div>
          </div>
        </div>
      );
    };
    return <SafeMiniAppScreen />;
  }

  // Определяем страницы которые не нуждаются в Layout
  const noLayoutPaths = ['/webauth'];
  const currentPath = typeof window !== 'undefined' ? window.location.pathname : '';
  const useLayout = !noLayoutPaths.includes(currentPath);

  const RouterImpl: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    // Всегда используем MemoryRouter для стабильности в WebView и браузере
    return <MemoryRouter>{children}</MemoryRouter>;
  };

  if (!mounted) {
    return (
      <div className="screen loading">
        <div className="spinner" />
      </div>
    );
  }

  const enableHeaderOnly = (() => {
    try {
      const url = new URL(window.location.href);
      if (url.searchParams.get('hdr') === '1') return true;
    } catch {}
    try {
      // vite env, читается на build‑времени; fallback к runtime
      // @ts-ignore
      const envFlag = import.meta?.env?.VITE_ENABLE_LAYOUT_HEADER;
      if (envFlag === '1' || envFlag === 'true') return true;
    } catch {}
    try {
      const runtime = (window as any).__SP_FLAGS__?.ENABLE_LAYOUT_HEADER;
      if (runtime) return true;
    } catch {}
    return false;
  })();

  // Временное отключение guard'ов регистрации для устранения циклов
  const enablePerms = false;

  const permsNoRedirect = (() => {
    try {
      const url = new URL(window.location.href);
      if (url.searchParams.get('perms_redirect') === '0') return true;
    } catch {}
    try {
      // @ts-ignore
      const envFlag = import.meta?.env?.VITE_PERMS_NO_REDIRECT;
      if (envFlag === '1' || envFlag === 'true') return true;
    } catch {}
    try {
      return (window as any).__SP_FLAGS__?.PERMS_NO_REDIRECT === true;
    } catch {}
    return false;
  })();

  const routesStage = (() => {
    try {
      const url = new URL(window.location.href);
      const s = url.searchParams.get('stage');
      if (s) return Math.max(1, Math.min(4, parseInt(s, 10) || 1));
    } catch {}
    try {
      // @ts-ignore
      const envFlag = import.meta?.env?.VITE_ROUTES_STAGE;
      if (envFlag) return Math.max(1, Math.min(4, parseInt(String(envFlag), 10) || 1));
    } catch {}
    try {
      const v = (window as any).__SP_FLAGS__?.ROUTES_STAGE;
      if (typeof v === 'number') return Math.max(1, Math.min(4, v));
    } catch {}
    return 1;
  })();

  return (
    <ConfigProvider theme={getAntdConfig(isTelegramWebApp)}>
      <RouterImpl>
        <PermissionsProvider>
          {/* Редирект незарегистрированных (роль start) на /register — отключаем при фичефлаге */}
          {enablePerms ? <RegistrationGuard noRedirect={permsNoRedirect} /> : null}
          {useLayout ? (
            <PlatformLayout activePersonality={getActivePersonalityName()} headerOnly={enableHeaderOnly}>
              <div className={(isTelegramWebApp ? 'telegram-mini-app ' : '') + (localStorage.getItem('sp_theme') || '')}>
                <Suspense fallback={<div className="screen loading"><div className="spinner" /></div>}>
                  <Routes>
                  <Route path="/" element={<TelegramHome />} />
                  <Route path="/webauth" element={<WebAuth />} />
                  <Route path="/register" element={<Register />} />
                  {routesStage >= 1 && (
                    <>
                      <Route path="/chat" element={<MiniAppChat />} />
                    </>
                  )}
                  {routesStage >= 2 && (
                    <>
                      <Route path="/soul/dashboard" element={<RoleGuard roles={["architect"]}><SoulDashboard /></RoleGuard>} />
                      <Route path="/soul/goals" element={<RoleGuard roles={["architect"]}><SoulGoals /></RoleGuard>} />
                      <Route path="/soul/activities-goals" element={<RoleGuard roles={["architect"]}><ActivityGoalsIntegration /></RoleGuard>} />
                      <Route path="/soul/optimization" element={<RoleGuard roles={["architect"]}><SoulOptimization /></RoleGuard>} />
                      <Route path="/soul/visualization" element={<RoleGuard roles={["architect"]}><SoulVisualization /></RoleGuard>} />
                      <Route path="/soul/logs" element={<SoulLogs />} />
                    </>
                  )}
                  {routesStage >= 3 && (
                    <>
                      <Route path="/architect" element={<RoleGuard roles={["architect"]}><ArchitectPanel /></RoleGuard>} />
                      <Route path="/admin" element={<RoleGuard roles={["admin","architect"]}><AdminPanel /></RoleGuard>} />
                      <Route path="/rbac-admin" element={<RoleGuard roles={["architect"]}><RBACAdmin /></RoleGuard>} />
                    </>
                  )}
                  {routesStage >= 4 && (
                    <>
                      <Route path="/original-home" element={<Home />} />
                      <Route path="/telegram-chat" element={<TelegramChat />} />
                      <Route path="/permission-demo" element={<PermissionDemo />} />
                      <Route path="/prompts" element={
                        <Prompts 
                          prompts={prompts}
                          selectedPrompt={selectedPrompt}
                          onPromptSelect={handlePromptSelect}
                          onPromptStatusChange={handlePromptStatusChange}
                          onSetActivePersonality={handleSetActivePersonality}
                          disableBasePersonality={disableBasePersonality}
                          onDisableBasePersonalityChange={handleUpdateSettings}
                        />
                      } />
                      <Route path="/settings" element={<Settings prompts={prompts} />} />
                      <Route path="/llm-settings" element={<LLMSettings />} />
                      <Route path="/payments" element={<Payments />} />
                      <Route path="/help" element={<Help />} />
                      <Route path="/chat-management" element={<ChatManagement />} />
                      <Route path="/keywords" element={<Keywords />} />
                      <Route path="/dates-reminders" element={<DatesRemindersV2 />} />
                      <Route path="/dates-reminders-old" element={<DatesReminders />} />
                      <Route path="/trace" element={<RoleGuard roles={["architect"]}><Trace /></RoleGuard>} />
                      <Route path="/llm-params" element={<RoleGuard roles={["architect"]}><LLMParams /></RoleGuard>} />
                      <Route path="/soul/quants" element={<RoleGuard roles={["architect"]}><SoulQuants /></RoleGuard>} />
                    </>
                  )}

                  {/* Fallback на домашнюю, чтобы избежать белого экрана при неизвестном роуте */}
                  <Route path="*" element={<TelegramHome />} />
                </Routes>
                </Suspense>
              </div>
            </PlatformLayout>
          ) : (
            <div className={(isTelegramWebApp ? 'telegram-mini-app ' : '') + (localStorage.getItem('sp_theme') || '')}>
              <Suspense fallback={<div className="screen loading"><div className="spinner" /></div>}>
              <Routes>
                <Route path="/" element={<TelegramHome />} />
                <Route path="/webauth" element={<WebAuth />} />
                <Route path="/register" element={<Register />} />
                {/* Fallback на домашнюю, чтобы избежать белого экрана при неизвестном роуте */}
                <Route path="*" element={<TelegramHome />} />
              </Routes>
              </Suspense>
            </div>
          )}
        </PermissionsProvider>
      </RouterImpl>
    </ConfigProvider>
  );
}

// Глобальный гард регистрации: если у пользователя роль start — отправляем на /register
const RegistrationGuard: React.FC<{ noRedirect?: boolean }> = ({ noRedirect = false }) => {
  const { state } = usePermsHook();
  useEffect(() => {
    try {
      const hasStart = state.roles.some(r => r.name === 'start');
      const path = window.location.pathname;
      if (hasStart && path !== '/register') {
        if (noRedirect === true) {
          console.log('[RegistrationGuard] start-role detected, but redirects disabled');
        } else {
          window.location.replace('/register');
        }
      }
    } catch {}
  }, [state.roles]);
  return null;
};

// Ограничитель по ролям: показывает children только для нужных ролей
const RoleGuard: React.FC<{ roles: string[]; children: React.ReactNode; fallback?: React.ReactNode }> = ({ roles, children, fallback = null }) => {
  const { state } = usePermsHook();
  const allowed = state.roles.some(r => roles.includes(r.name));
  if (!allowed) return <>{fallback || null}</>;
  return <>{children}</>;
};
