import React, { createContext, useContext, useEffect, useState } from 'react';
import { buildAuthHeaders } from '../api';

// Типы для системы полномочий
export interface UserRole {
  id: number;
  name: string;
  description?: string;
  is_system: boolean;
}

export interface UserPermission {
  id: number;
  key: string;
  description?: string;
}

export interface UserLimits {
  daily_requests?: number;
  monthly_requests?: number;
  max_input_tokens?: number;
  max_output_tokens?: number;
}

export interface PermissionsState {
  roles: UserRole[];
  permissions: string[];
  limits: UserLimits;
  loading: boolean;
  error: string | null;
}

// Контекст для системы полномочий
const PermissionsContext = createContext<{
  state: PermissionsState;
  hasPermission: (permission: string) => boolean;
  hasRole: (roleName: string) => boolean;
  checkLimits: (action: string) => boolean;
  refreshPermissions: () => Promise<void>;
} | null>(null);

// Провайдер контекста полномочий
export const PermissionsProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [state, setState] = useState<PermissionsState>({
    roles: [],
    permissions: [],
    limits: {},
    loading: true,
    error: null,
  });

  // Получение текущих полномочий пользователя
  const fetchPermissions = async () => {
    try {
      setState(prev => ({ ...prev, loading: true, error: null }));

      // Получаем Telegram ID из sessionStorage или WebApp
      const getTelegramId = () => {
        const storedId = sessionStorage.getItem('tg_id');
        if (storedId) return storedId;
        
        if (typeof window !== 'undefined' && (window as any).Telegram?.WebApp) {
          const webAppUser = (window as any).Telegram.WebApp.initDataUnsafe?.user;
          return webAppUser?.id?.toString();
        }
        
        return null;
      };

      const telegramId = getTelegramId();
      if (!telegramId) {
        // Для веб версии просто не загружаем полномочия, пока нет авторизации
        setState(prev => ({
          ...prev,
          loading: false,
          error: null,
        }));
        return;
      }

      // Запрашиваем полномочия пользователя
      const response = await fetch('/api/user-management/my-permissions', { headers: buildAuthHeaders() });

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      const data = await response.json();
      const roles = (data.roles || []).map((r: any) => ({ id: r.id, name: r.name, description: r.description }));
      const permissions = Array.isArray(data.permissions) ? data.permissions : [];
      setState({
        roles,
        permissions,
        limits: {},
        loading: false,
        error: null,
      });
    } catch (error) {
      console.error('Ошибка загрузки полномочий:', error);
      setState(prev => ({
        ...prev,
        loading: false,
        error: error instanceof Error ? error.message : 'Неизвестная ошибка',
      }));
    }
  };

  // Проверка наличия конкретного права
  const hasPermission = (permission: string): boolean => {
    return state.permissions.includes(permission);
  };

  // Проверка наличия роли
  const hasRole = (roleName: string): boolean => {
    return state.roles.some(role => role.name === roleName);
  };

  // Проверка лимитов
  const checkLimits = (action: string): boolean => {
    // Здесь можно добавить логику проверки лимитов
    // Например, для daily_requests, max_tokens и т.д.
    return true;
  };

  // Обновление полномочий
  const refreshPermissions = async () => {
    await fetchPermissions();
  };

  useEffect(() => {
    fetchPermissions();
  }, []);

  return (
    <PermissionsContext.Provider
      value={{
        state,
        hasPermission,
        hasRole,
        checkLimits,
        refreshPermissions,
      }}
    >
      {children}
    </PermissionsContext.Provider>
  );
};

// Хук для использования системы полномочий
export const usePermissions = () => {
  const context = useContext(PermissionsContext);
  if (!context) {
    throw new Error('usePermissions должен использоваться внутри PermissionsProvider');
  }
  return context;
};

// Компонент для условного рендеринга на основе полномочий
export const PermissionGate: React.FC<{
  permission?: string;
  role?: string;
  fallback?: React.ReactNode;
  children: React.ReactNode;
}> = ({ permission, role, fallback = null, children }) => {
  const { hasPermission, hasRole } = usePermissions();

  const hasAccess = () => {
    if (permission && !hasPermission(permission)) return false;
    if (role && !hasRole(role)) return false;
    return true;
  };

  return hasAccess() ? <>{children}</> : <>{fallback}</>;
};

// Хук для определения платформы (веб или мини-апп)
export const usePlatform = () => {
  const [platform, setPlatform] = useState<'web' | 'miniapp' | 'unknown'>('unknown');

  useEffect(() => {
    const detectPlatform = () => {
      // Проверяем наличие Telegram WebApp
      const isTelegramWebApp = typeof window !== 'undefined' && (
        ((window as any).Telegram && (window as any).Telegram.WebApp) ||
        window.location.hostname.includes('t.me') ||
        window.location.hostname.includes('telegram.org') ||
        document.body.classList.contains('telegram-mini-app')
      );

      if (isTelegramWebApp) {
        setPlatform('miniapp');
      } else {
        setPlatform('web');
      }
    };

    detectPlatform();
  }, []);

  return {
    platform,
    isMiniApp: platform === 'miniapp',
    isWeb: platform === 'web',
  };
};

// Компонент для условного рендеринга на основе платформы
export const PlatformGate: React.FC<{
  platform: 'web' | 'miniapp';
  children: React.ReactNode;
  fallback?: React.ReactNode;
}> = ({ platform: targetPlatform, children, fallback = null }) => {
  const { platform } = usePlatform();
  
  return platform === targetPlatform ? <>{children}</> : <>{fallback}</>;
};
