import React from 'react'
// @ts-ignore
import * as ReactDOMLegacy from 'react-dom'
import App from './App.tsx'
// CSS импорты перенесены в App.tsx для правильного порядка

class RootErrorBoundary extends React.Component<React.PropsWithChildren, { hasError: boolean; error?: any; info?: any }>{
  constructor(props:any){
    super(props);
    this.state = { hasError: false };
  }
  static getDerivedStateFromError(error:any){
    return { hasError: true, error };
  }
  componentDidCatch(error:any, info:any){
    // Логируем максимум деталей в консоль, чтобы понять причину белого экрана
    // Не используем внешние репортеры
    // eslint-disable-next-line no-console
    console.error('[ROOT] Uncaught render error:', error, info);
    this.setState({ info });
  }
  render(){
    if (this.state.hasError){
      const details = (this.state.error?.stack || String(this.state.error || 'unknown')).toString();
      // Быстрые диагностические данные
      let wa:any=null, uid:string|null=null, stored:string|null=null;
      try{ wa=(window as any).Telegram?.WebApp; uid=wa?.initDataUnsafe?.user?.id?.toString()||null; stored=sessionStorage.getItem('tg_id'); }catch{}
      return (
        <div style={{padding:16, fontFamily:'ui-monospace, monospace', background:'#1f2937', color:'#fde68a', minHeight:'100vh'}}>
          <div style={{fontWeight:700, marginBottom:8}}>❗ Критическая ошибка рендера UI</div>
          <div style={{whiteSpace:'pre-wrap', fontSize:12}}>{details.substring(0, 4000)}</div>
          <div style={{marginTop:12, fontSize:12, color:'#93c5fd'}}>
            <div>diag.wa: {String(!!wa)}</div>
            <div>diag.uid: {uid || 'null'}</div>
            <div>diag.sessionStorage.tg_id: {stored || 'null'}</div>
          </div>
        </div>
      );
    }
    return this.props.children as any;
  }
}

function ensureRootElement(): HTMLElement {
  try {
    const el = document.getElementById('root');
    if (el) return el;
  } catch {}
  const created = document.createElement('div');
  created.id = 'root';
  document.body.appendChild(created);
  return created;
}

const rootEl = ensureRootElement();
// Сигнал готовности для снятия FOUC
try { document.documentElement.classList.add('sp-ready'); } catch {}

// Диагностический режим и обход React управляются ТОЛЬКО через __SP_FLAGS__
// Управление безопасным режимом через query-параметры. По умолчанию SAFE_BOOT отключён.
try {
  const ua = navigator.userAgent || '';
  const isTg = /Telegram/i.test(ua) || !!(window as any).Telegram?.WebApp;
  const flags = (window as any).__SP_FLAGS__ || {};
  const usp = new URLSearchParams((typeof window !== 'undefined' && window.location.search) || '');
  const safeParam = usp.get('safe');
  const diagParam = usp.get('diag');
  flags.SAFE_BOOT = safeParam === '1' ? true : false;
  flags.NOREACT = false;
  flags.DIAG = diagParam === '1' ? true : false;
  if (isTg && flags.SAFE_BOOT) {
    // При включённом safe не дёргать тяжёлые пути
  }
  (window as any).__SP_FLAGS__ = flags;
} catch {}

const DIAG = (() => {
  try { return (window as any).__SP_FLAGS__?.DIAG === true; } catch { return false; }
})();
const NOREACT = (() => {
  try { return (window as any).__SP_FLAGS__?.NOREACT === true; } catch { return false; }
})();

const BootDiag: React.FC = () => {
  let wa: any = null;
  let uid: string | null = null;
  try {
    wa = (window as any).Telegram?.WebApp;
    uid = wa?.initDataUnsafe?.user?.id?.toString() || null;
    if (uid) sessionStorage.setItem('tg_id', String(uid));
  } catch {}
  const stored = sessionStorage.getItem('tg_id');
  return (
    <div style={{padding:16, fontFamily:'ui-monospace, monospace'}}>
      <h3>Boot Diag</h3>
      <div>wa: {String(!!wa)}</div>
      <div>uid: {uid || 'null'}</div>
      <div>sessionStorage.tg_id: {stored || 'null'}</div>
    </div>
  );
};

// Полный обход React (диагностика WebView): ?noreact=1
if (NOREACT) {
  try {
    const wa: any = (window as any).Telegram?.WebApp;
    const uid = wa?.initDataUnsafe?.user?.id;
    if (uid) sessionStorage.setItem('tg_id', String(uid));
  } catch {}
  const tg = sessionStorage.getItem('tg_id') || 'null';
  rootEl.innerHTML = `<div style="padding:16px;font-family:ui-monospace,monospace">
      <h3>MiniApp minimal</h3>
      <div>wa: ${String(!!(window as any).Telegram?.WebApp)}</div>
      <div>tg_id: ${tg}</div>
    </div>`;
} else {
  // Используем легаси-рендер для совместимости с некоторыми версиями Telegram WebView (устранение React #300)
  // @ts-ignore
  ReactDOMLegacy.render(
    <RootErrorBoundary>
      {DIAG ? <BootDiag /> : <App />}
    </RootErrorBoundary>,
    rootEl
  );
}
