import React, { useEffect, useState } from 'react';
import { getTelegramUser } from '../api';

// Авторизация через мини-приложение Telegram
// 1) Проверяет, запущено ли приложение из Telegram WebApp
// 2) Если да - перенаправляет в основной интерфейс
// 3) Если нет - показывает инструкцию по запуску из мини-приложения

const WebAuth: React.FC = () => {
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    console.log('[WEBAUTH] 🚀 Проверяем авторизацию через Telegram WebApp...');

    // Проверяем, запущено ли приложение из Telegram
    const checkTelegramAuth = async () => {
      // Проверяем URL параметры на наличие данных пользователя
      const urlParams = new URLSearchParams(window.location.search);
      const tgIdParam = urlParams.get('tg_id');
      const userDataParam = urlParams.get('user_data');
      const otpParam = urlParams.get('otp');

      console.log('[WEBAUTH] 🔍 URL параметры:', { tgIdParam, userDataParam, otp: otpParam ? 'найден' : 'не найден' });

      // 1. Приоритет: данные из URL параметров (переход из мини-приложения)
      if (tgIdParam && userDataParam) {
        try {
          // URLSearchParams уже декодирует значение, поэтому повторно декодировать не нужно
          const userData = JSON.parse(userDataParam);
          console.log('[WEBAUTH] ✅ Найдены данные пользователя в URL:', userData);
          
          // Если есть OTP токен - проверяем его на сервере
          if (otpParam) {
            console.log('[WEBAUTH] 🔐 Проверяем OTP токен...');
            
            try {
              const response = await fetch('/api/web-auth/verify-otp', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                  tg_id: parseInt(tgIdParam),
                  otp: otpParam
                })
              });
              
              if (response.ok) {
                const data = await response.json();
                console.log('[WEBAUTH] ✅ OTP токен валидный, авторизация успешна');
                
                // Сохраняем токен авторизации
                if (data.token) {
                  sessionStorage.setItem('token', data.token);
                }
              } else {
                console.warn('[WEBAUTH] ⚠️ OTP токен невалидный, используем обычную авторизацию');
                // Продолжаем без OTP проверки
              }
            } catch (otpError) {
              console.warn('[WEBAUTH] ⚠️ Ошибка проверки OTP:', otpError);
              // Продолжаем без OTP проверки
            }
          }
          
          sessionStorage.setItem('tg_id', tgIdParam);
          sessionStorage.setItem('telegram_user', JSON.stringify(userData));
          
          setLoading(false);
          
          // Очищаем URL от параметров и перенаправляем на главную
          const cleanUrl = window.location.origin + window.location.pathname;
          window.history.replaceState({}, document.title, cleanUrl);
          window.location.replace('/');
          return;
        } catch (e) {
          console.error('[WEBAUTH] ❌ Ошибка парсинга данных из URL:', e);
        }
      }

      // 2. Проверяем Telegram WebApp (если приложение запущено в Telegram)
      const isTelegram = typeof window !== 'undefined' && !!(window as any).Telegram?.WebApp;
      if (isTelegram) {
        try { (window as any).Telegram?.WebApp?.ready?.(); } catch {}
        const telegramUser = getTelegramUser();
        if (telegramUser && telegramUser.id) {
          console.log('[WEBAUTH] ✅ Пользователь авторизован через Telegram WebApp:', telegramUser.id);
          sessionStorage.setItem('tg_id', String(telegramUser.id));
          sessionStorage.setItem('telegram_user', JSON.stringify(telegramUser));
        } else {
          console.log('[WEBAUTH] ⚠️ Telegram WebApp без initDataUnsafe.user; продолжаем без блока');
        }
        setLoading(false);
        window.location.replace('/');
        return;
      }

      // 3. Проверяем существующие данные в SessionStorage
      const existingTgId = sessionStorage.getItem('tg_id');
      const existingUser = sessionStorage.getItem('telegram_user');
      
      if (existingTgId && existingUser) {
        console.log('[WEBAUTH] ✅ Найдены сохраненные данные авторизации:', existingTgId);
        setLoading(false);
        window.location.replace('/');
        return;
      }

      console.log('[WEBAUTH] ❌ Авторизация не найдена');
      setLoading(false);
      setError('Приложение должно быть запущено из Telegram мини-приложения');
    };

    // Небольшая задержка для инициализации Telegram WebApp
    setTimeout(checkTelegramAuth, 200);
  }, []);

  if (loading) {
    return (
      <div style={{
        minHeight: '100vh',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        flexDirection: 'column',
        gap: 16,
        backgroundColor: '#f5f5f5'
      }}>
        <div style={{ fontSize: '18px', color: '#666' }}>Проверяем авторизацию...</div>
        <div style={{
          width: '40px',
          height: '40px',
          border: '4px solid #f3f3f3',
          borderTop: '4px solid #3498db',
          borderRadius: '50%',
          animation: 'spin 1s linear infinite'
        }}></div>
        <style>{`
          @keyframes spin {
            0% { transform: rotate(0deg); }
            100% { transform: rotate(360deg); }
          }
        `}</style>
      </div>
    );
  }

  return (
    <div style={{
      minHeight: '100vh',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      flexDirection: 'column',
      gap: 24,
      padding: '20px',
      backgroundColor: '#f5f5f5',
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif'
    }}>
      <div style={{
        backgroundColor: 'white',
        borderRadius: '12px',
        padding: '32px',
        boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)',
        textAlign: 'center',
        maxWidth: '500px',
        width: '100%'
      }}>
        <div style={{
          width: '64px',
          height: '64px',
          backgroundColor: '#e3f2fd',
          borderRadius: '50%',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          margin: '0 auto 24px',
          fontSize: '32px'
        }}>
          ⚠️
        </div>

        <h1 style={{
          fontSize: '24px',
          fontWeight: '600',
          color: '#333',
          margin: '0 0 16px 0'
        }}>
          Требуется авторизация
        </h1>

        <p style={{
          fontSize: '16px',
          color: '#666',
          margin: '0 0 24px 0',
          lineHeight: '1.5'
        }}>
          Это веб-приложение работает только в рамках Telegram мини-приложения.
          Пожалуйста, откройте приложение через Telegram бота.
        </p>

        {error && (
          <div style={{
            backgroundColor: '#ffebee',
            color: '#c62828',
            padding: '12px',
            borderRadius: '8px',
            marginBottom: '24px',
            border: '1px solid #ffcdd2'
          }}>
            {error}
          </div>
        )}

        <div style={{
          backgroundColor: '#f8f9fa',
          padding: '20px',
          borderRadius: '8px',
          textAlign: 'left'
        }}>
          <h3 style={{
            fontSize: '16px',
            fontWeight: '600',
            color: '#333',
            margin: '0 0 12px 0'
          }}>
            📱 Как открыть приложение:
          </h3>
          <ol style={{
            margin: 0,
            paddingLeft: '20px',
            color: '#555',
            lineHeight: '1.6'
          }}>
            <li>Откройте Telegram</li>
            <li>Найдите бота <strong>@test_SoulPulse_bot</strong></li>
            <li>Запустите мини-приложение</li>
            <li>Приложение откроется автоматически</li>
          </ol>
        </div>

        <div style={{
          marginTop: '24px',
          padding: '12px',
          backgroundColor: '#e8f5e8',
          borderRadius: '8px',
          fontSize: '14px',
          color: '#2e7d32'
        }}>
          💡 <strong>Безопасность:</strong> Приложение получает доступ только к вашим данным в Telegram и сохраняет их только на время сессии.
        </div>
      </div>
    </div>
  );
};

export default WebAuth;


