// Для локальной разработки используем localhost:8000, для продакшена - относительный путь
const API_BASE = (() => {
  console.log('[API_BASE] 🎯 Определяем API_BASE...');

  const envBase = (import.meta as any).env?.VITE_API_URL as string | undefined;
  const host = typeof window !== 'undefined' ? window.location.hostname : '';
  const protocol = typeof window !== 'undefined' ? window.location.protocol : 'http:';
  const port = typeof window !== 'undefined' ? window.location.port : '';

  console.log('[API_BASE] 🌐 Host:', host);
  console.log('[API_BASE] 🔗 Protocol:', protocol);
  console.log('[API_BASE] 🚪 Port:', port);
  console.log('[API_BASE] 📝 VITE_API_URL:', envBase);

  // Хосты *.soulpulse.art всегда используют относительный /api (чтобы не уехать на localhost)
  if (host.endsWith('soulpulse.art')) {
    const relativeBase = '/api';
    console.log('[API_BASE] ✅ Using relative API for production domain:', relativeBase);
    return relativeBase;
  }

  // Приоритет: явная переменная окружения (не для *.soulpulse.art)
  if (envBase && envBase.trim()) {
    const cleanEnvBase = envBase.replace(/\/$/, '');
    console.log('[API_BASE] ✅ Using VITE_API_URL:', cleanEnvBase);
    return cleanEnvBase;
  }

  const isLocal = host === 'localhost' || host === '127.0.0.1';

  // Локально ходим на локальный бэкенд
  if (isLocal) {
    const localBase = 'http://localhost:8000/api';
    console.log('[API_BASE] ✅ Using local API_BASE:', localBase);
    return localBase;
  }

  // В продакшене используем относительный путь (тот же домен)
  const relativeBase = '/api';
  console.log('[API_BASE] ✅ Using relative API_BASE:', relativeBase);
  return relativeBase;
})();

// Экспортируем API_BASE для отладки
export { API_BASE };
console.log('[API] 🎯 Итоговый API_BASE:', API_BASE);

export function buildAuthHeaders(): HeadersInit {
  const headers: Record<string, string> = { "Content-Type": "application/json" };
  const tgId = sessionStorage.getItem('tg_id') || (typeof window !== 'undefined' && (window as any).Telegram?.WebApp?.initDataUnsafe?.user?.id?.toString()) || '';
  if (tgId) headers['X-Telegram-User-ID'] = tgId;
  const token = sessionStorage.getItem('token') || localStorage.getItem('token');
  if (token) headers['Authorization'] = `Bearer ${token}`;
  return headers;
}

export async function api<T>(path: string, opts: RequestInit = {}): Promise<T> {
  const headers: HeadersInit = { ...buildAuthHeaders(), ...(opts.headers || {}) };

  const res = await fetch(`${API_BASE}${path}`, { ...opts, headers });
  if (!res.ok) throw new Error(`${res.status} ${res.statusText}`);
  return res.json();
}

// Авторизация через backend API
async function authenticateWithBackend(initData: string): Promise<void> {
  try {
    console.log('[AUTH] 🔐 Authenticating with backend...');
    
    // Используем dev endpoint для локального тестирования
    const endpoint = window.location.hostname === 'localhost' 
      ? '/miniapp/auth/verify-dev' 
      : '/miniapp/auth/verify';
    
    const response = await fetch(`${API_BASE}${endpoint}`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ initData }),
    });

    if (response.ok) {
      const data = await response.json();
      console.log('[AUTH] ✅ Backend auth successful');
      
      // Сохраняем JWT токен
      if (data.token) {
        sessionStorage.setItem('token', data.token);
        console.log('[AUTH] 💾 JWT token saved');
      }
      
      // Сохраняем данные пользователя
      if (data.user) {
        sessionStorage.setItem('user', JSON.stringify(data.user));
        console.log('[AUTH] 👤 User data saved');
      }
    } else {
      console.error('[AUTH] ❌ Backend auth failed:', response.status, response.statusText);
      const errorText = await response.text();
      console.error('[AUTH] 📄 Error details:', errorText);
    }
  } catch (error) {
    console.error('[AUTH] 💥 Backend auth error:', error);
  }
}

// Функция для получения данных пользователя Telegram
export function getTelegramUser() {
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] [AUTH] 🔍 Проверяем Telegram WebApp...`);
  console.log(`[${timestamp}] [AUTH] 🌐 Window defined:`, typeof window !== 'undefined');
  console.log(`[${timestamp}] [AUTH] 📱 Telegram exists:`, !!(window as any).Telegram);
  console.log(`[${timestamp}] [AUTH] 🤖 WebApp exists:`, !!(window as any).Telegram?.WebApp);
  console.log(`[${timestamp}] [AUTH] 👤 initDataUnsafe.user exists:`, !!(window as any).Telegram?.WebApp?.initDataUnsafe?.user);

  // 0) Быстрый путь для веб-версии: сначала пробуем SessionStorage
  const storedUser = sessionStorage.getItem('telegram_user');
  const tgId = sessionStorage.getItem('tg_id');

  console.log(`[${timestamp}] [AUTH] 💾 SessionStorage tg_id:`, tgId);
  console.log(`[${timestamp}] [AUTH] 💾 SessionStorage user:`, storedUser);

  if (storedUser && tgId) {
    try {
      const user = JSON.parse(storedUser);
      console.log(`[${timestamp}] [AUTH] ✅ User from sessionStorage:`, user.id);
      return user;
    } catch (e) {
      console.warn(`[${timestamp}] [AUTH] Ошибка парсинга данных пользователя из sessionStorage:`, e);
    }
  }

  // 1) Минимальная проверка: берем только tg_id из Telegram WebApp или sessionStorage
  try {
    const wa = (window as any).Telegram?.WebApp;
    const uid = wa?.initDataUnsafe?.user?.id;
    if (uid) {
      sessionStorage.setItem('tg_id', String(uid));
      return { id: uid } as any;
    }
  } catch {}

  if (tgId) {
    // Если есть только tg_id, создаем минимальный объект пользователя
    const user = { id: parseInt(tgId, 10) };
    console.log(`[${timestamp}] [AUTH] ⚠️ Только tg_id из sessionStorage:`, user.id);
    return user as any;
  }

  console.warn(`[${timestamp}] [AUTH] Пользователь недоступен (ни SessionStorage, ни WebApp). Для web требуется /webauth.`);
  return null as any;
}

// Универсальная функция для API запросов с поддержкой различных методов
export async function apiRequest(
  url: string,
  method: 'GET' | 'POST' | 'PUT' | 'DELETE' = 'GET',
  body: any = null,
  customHeaders: Record<string, string> = {}
): Promise<any> {
  console.log('[API] 🚀 Начинаем API запрос...');
  console.log('[API] 📍 URL:', url);
  console.log('[API] 📝 Method:', method);
  console.log('[API] 📦 Body:', body);
  console.log('[API] 📋 Custom headers:', customHeaders);

  const headers: HeadersInit = { ...buildAuthHeaders(), ...customHeaders };

  const options: RequestInit = {
    method,
    headers,
  };

  if (body && method !== 'GET') {
    options.body = JSON.stringify(body);
  }

  // Добавляем timestamp для обхода кэширования
  const separator = url.includes('?') ? '&' : '?';
  const timestampedUrl = `${url}${separator}_cache_bust=${Date.now()}`;
  const fullUrl = timestampedUrl.startsWith('http') ? timestampedUrl : `${API_BASE}${timestampedUrl}`;

  console.log('[API] 🌐 Final URL:', fullUrl);
  console.log('[API] 🏠 API_BASE:', API_BASE);
  console.log('[API] ⚙️ Request options:', JSON.stringify(options, null, 2));

  try {
    console.log('[API] 📡 Отправляем запрос...');
    const response = await fetch(fullUrl, options);
    console.log('[API] 📶 Response status:', response.status);
    console.log('[API] 📶 Response statusText:', response.statusText);
    console.log('[API] 📶 Response headers:', Object.fromEntries(response.headers.entries()));

    if (!response.ok) {
      const errorText = await response.text();
      console.error('[API] ❌ HTTP Error:', response.status, response.statusText);
      console.error('[API] 📄 Error response text:', errorText);
      throw new Error(`HTTP ${response.status}: ${response.statusText} - ${errorText}`);
    }

    // Проверяем Content-Type
    const contentType = response.headers.get('Content-Type') || '';
    console.log('[API] 📋 Content-Type:', contentType);

    if (!contentType.includes('application/json')) {
      const htmlText = await response.text();
      console.error('[API] 🚨 ПОЛУЧЕН HTML ВМЕСТО JSON!');
      console.error('[API] 📄 HTML содержимое (первые 500 символов):', htmlText.substring(0, 500));
      throw new Error(`API вернул HTML вместо JSON! Content-Type: ${contentType}`);
    }

    const responseData = await response.json();
    console.log('[API] ✅ Успешный ответ:', JSON.stringify(responseData, null, 2));
    return responseData;

  } catch (error) {
    console.error('[API] 💥 Ошибка при выполнении запроса:', error);
    throw error;
  }
}